shell_commands:
node --input-type=module -e "
import {ToolRegistry} from './dist/orchestration/tools/registry.js';

const registry = new ToolRegistry();
registry.register(
  {
    name: 'type_check_tool',
    description: 'A tool for type checking',
    inputSchema: {
      type: 'object',
      properties: {userId: {type: 'string'}},
      required: ['userId'],
    },
  },
  async () => 'success'
);

const response = await registry.execute('type_check_tool', {userId: 12345});
console.log('Error message:', response.result);
console.log('Includes userId:', response.result.includes('userId'));
console.log('Includes string:', response.result.includes('string'));
console.log('Includes 12345:', response.result.includes('12345'));
"
